            new Quote { Id = "https://fr.wikiquote.org/wiki/Alexandre_Dumas", Text = "Les vastes horizons, la mer infinie, les montagnes gigantesques, surtout lorsque tout cela est baigné de l'air pur et doré du Midi, tout cela vous mène droit à la contemplation, et rien mieux que la contemplation ne vous éloigne du travail [...].", Author = "Alexandre Dumas" },
